10	// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
11	// 不能再改期、取消或重新开启。
12	const (
13		PlanStatusOpen     = "未完成"
14		PlanStatusDone     = "已完成"
15		PlanStatusCanceled = "已取消"
16	)
17	
18	// 待办相对本机今天的标记。
19	const (
20		TodoToday   = "今天需校准"
21		TodoOverdue = "逾期"
22		TodoFuture  = "未到计划日"
23	)
24	
25	// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
26	type PlanChange struct {
27		From      string `json:"from"`
28		To        string `json:"to"`
29		ChangedAt string `json:"changed_at"`
30		Reason    string `json:"reason"`
31	}
32	
33	// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
34	type Plan struct {
35		Number       string `json:"number"`
36		InstrumentID string `json:"instrument_id"`
37		// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
38		PlannedDate  string       `json:"planned_date"`
39		OriginalDate string       `json:"original_date"`
40		Note         string       `json:"note"`
41		CreatedAt    string       `json:"created_at"`
42		Changes      []PlanChange `json:"changes,omitempty"`
43		Status       string       `json:"status"`
44		// 取消时保留原计划日期、取消时间和原因。
45		CanceledAt   string `json:"canceled_at,omitempty"`
46		CancelReason string `json:"cancel_reason,omitempty"`
47		// 完成时保存完成时间和所用证书编号。
48		CompletedAt       string `json:"completed_at,omitempty"`
49		CertificateNumber string `json:"certificate_number,omitempty"`
50	}
51	
52	// Open 报告计划是否尚未结束（未完成、未取消）。
53	func (p Plan) Open() bool { return p.Status == PlanStatusOpen }
54	
55	// PlanInput 是建立校准计划的输入。
56	type PlanInput struct {
57		Number       string
58		InstrumentID string
59		Date         string
60		Note         string
61	}
62	
63	func (l *Ledger) findPlan(number string) *Plan {
64		for i := range l.data.Plans {
65			if l.data.Plans[i].Number == number {
66				return &l.data.Plans[i]
67			}
68		}
69		return nil
70	}
71	
72	// cloneChanges 返回改期历史切片的独立副本，使对外返回的计划与台账内部
73	// 存储不共享底层数组：调用方调换顺序、删改或追加展示用记录，不会改写
74	// 正式的改期历史。nil 保持 nil，以维持“没有改期历史”的既有表现。
75	func cloneChanges(in []PlanChange) []PlanChange {
76		if in == nil {
77			return nil
78		}
79		return append([]PlanChange(nil), in...)
80	}
81	
82	// clonePlan 返回计划的独立深拷贝，连同改期历史一起复制。
83	func clonePlan(p Plan) Plan {
84		p.Changes = cloneChanges(p.Changes)
85		return p
86	}
87	
88	// clonePlanPtr 返回台账内计划的独立深拷贝；找不到时返回 nil。
89	// 各计划操作返回的计划只是已保存内容的展示副本：调用方为了显示而改动
90	// 编号、日期、状态、关联证书或改期记录，都不能成为绕过计划操作直接改写
91	// 台账的途径，也不会在此后正常写盘时被带入台账文件。
92	func clonePlanPtr(p *Plan) *Plan {
93		if p == nil {
94			return nil
95		}
96		cp := clonePlan(*p)
97		return &cp
98	}
99	
100	// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于 now 所在的本机
101	// 日历日期。调用方传入本次操作开始时所取的本机时间，使日期合法性与操作
102	// 记录的时间对应同一时刻。
103	func (l *Ledger) validatePlanDate(raw, field string, now time.Time) (string, error) {
104		_, text, err := parseFiniteDate(raw, field)
105		if err != nil {
106			return "", err
107		}
108		todayText := now.Format(DateLayout)
109		if text < todayText {
110			return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
111		}
112		return text, nil
113	}
114	
115	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
116	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
117	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
118	// 不新增或改动任何记录。
119	//
120	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
121	// 台账（含同一对象随后的计划查询、按器具核对与待办）与建立前完全一致——
122	// 失败的计划既不占用编号，也不占用该器具唯一的未结束计划名额，更不会在此后
123	// 其他成功操作写盘时被顺带写入；文件仍不可写时再次提交相同编号仍报保存错误
124	// （不会被当成编号重复或器具已有未结束计划而拒绝），恢复可写后无需重新打开
125	// 台账，重新提交才真正建立，建立时间取本次成功申请的时间。
126	//
127	// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
128	// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
129	// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
130	// 重新查询同一台账得到的仍是最后成功保存的计划。
131	// 每次建立申请只在开始处理时取一次本机时间：计划日期是否不早于“今天”
132	// 按该时刻的日历日期判断，正式保存的建立时间也取该时刻——即使校验与写盘
133	// 之间跨过午夜，建立时间仍属于申请开始的日历日期，当天计划不会被记成
134	// 次日建立，也不会在随后用申请当天的证书完成时被误判为证书早于建立。
135	// 该时刻不延续到下一次申请：下次建立重新取当时的本机时间判断。
136	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
137		now := l.now()
138		number, err := cleanText(in.Number)
139		if err != nil {
140			return nil, fmt.Errorf("计划编号无效：%w", err)
141		}
142		instID, err := cleanText(in.InstrumentID)
143		if err != nil {
144			return nil, fmt.Errorf("器具编号无效：%w", err)
145		}
146		note, err := cleanText(in.Note)
147		if err != nil {
148			return nil, fmt.Errorf("计划说明无效：%w", err)
149		}
150		if l.findInstrument(instID) == nil {
151			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
152		}
153		dateText, err := l.validatePlanDate(in.Date, "计划日期", now)
154		if err != nil {
155			return nil, err
156		}
157		if l.findPlan(number) != nil {
158			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
159		}
160		for i := range l.data.Plans {
161			p := &l.data.Plans[i]
162			if p.InstrumentID == instID && p.Open() {
163				return nil, validationError(
164					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
165					instID, p.Number, p.PlannedDate)
166			}
167		}
168		p := Plan{
169			Number:       number,
170			InstrumentID: instID,
171			PlannedDate:  dateText,
172			OriginalDate: dateText,
173			Note:         note,
174			CreatedAt:    now.Format(time.RFC3339),
175			Status:       PlanStatusOpen,
176		}
177		// 在独立的新切片上暂存新计划：只有原子替换台账文件成功后才提交。
178		// 写盘失败时恢复原切片，保证同一台账对象随后看到的计划查询、待办与
179		// 按器具核对都与建立前一致——失败计划不占用编号或该器具唯一的未结束
180		// 计划名额，再次提交仍会走到保存而不会被当成重复计划拒绝，失败计划也
181		// 不会被之后的写盘顺带写入。
182		original := l.data.Plans
183		staged := make([]Plan, 0, len(original)+1)
184		staged = append(staged, original...)
185		staged = append(staged, p)
186		l.data.Plans = staged
187		if err := l.save(); err != nil {
188			l.data.Plans = original
189			return nil, err
190		}
191		return clonePlanPtr(l.findPlan(number)), nil
192	}
193	
194	// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
195	func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
196		p := l.findPlan(number)
197		if p == nil {
198			return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
199		}
200		if !p.Open() {
201			return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
202				number, p.Status)
203		}
204		return p, nil
205	}
206	
207	// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
208	// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
209	// 找不到计划或计划已结束时拒绝且不改动记录。
210	//
211	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
212	// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
213	// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
214	// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
215	// 且只新增一条从最后成功保存的日期到新日期的记录。
216	//
217	// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
218	// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
219	// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
220	// 此前分别取得的操作结果、计划查询结果和核对结果。
221	func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
222		// 本次改期只取一次本机时间：新日期的合法性判断与留痕的操作时间对应
223		// 同一时刻，跨午夜不会分裂到两天。
224		now := l.now()
225		number, err := cleanText(number)
226		if err != nil {
227			return nil, fmt.Errorf("计划编号无效：%w", err)
228		}
229		reason, err = cleanText(reason)
230		if err != nil {
231			return nil, fmt.Errorf("改期原因无效：%w", err)
232		}
233		dateText, err := l.validatePlanDate(newDate, "新计划日期", now)
234		if err != nil {
235			return nil, err
236		}
237		p, err := l.requireOpenPlan(number)
238		if err != nil {
239			return nil, err
240		}
241		// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
242		change := PlanChange{
243			From:      p.PlannedDate,
244			To:        dateText,
245			ChangedAt: now.Format(time.RFC3339),
246			Reason:    reason,
247		}
248		// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
249		// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
250		// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
251		original := l.data.Plans
252		staged := make([]Plan, len(original))
253		copy(staged, original)
254		for i := range staged {
255			if staged[i].Number != number {
256				continue
257			}
258			staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
259			staged[i].PlannedDate = dateText
260		}
261		l.data.Plans = staged
262		if err := l.save(); err != nil {
263			l.data.Plans = original
264			return nil, err
265		}
266		return clonePlanPtr(l.findPlan(number)), nil
267	}
268	
269	// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
270	// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
271	//
272	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
273	// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
274	// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
275	// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
276	// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
277	// 取消，取消时间和原因取本次成功提交而非失败那次。
278	//
279	// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
280	// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
281	func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
282		number, err := cleanText(number)
283		if err != nil {
284			return nil, fmt.Errorf("计划编号无效：%w", err)
285		}
286		reason, err = cleanText(reason)
287		if err != nil {
288			return nil, fmt.Errorf("取消原因无效：%w", err)
289		}
290		if _, err := l.requireOpenPlan(number); err != nil {
291			return nil, err
292		}
293		canceledAt := l.now().Format(time.RFC3339)
294		// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
295		// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
296		// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
297		// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
298		original := l.data.Plans
299		staged := make([]Plan, len(original))
300		copy(staged, original)
301		for i := range staged {
302			if staged[i].Number != number {
303				continue
304			}
305			staged[i].Status = PlanStatusCanceled
306			staged[i].CanceledAt = canceledAt
307			staged[i].CancelReason = reason
308		}
309		l.data.Plans = staged
310		if err := l.save(); err != nil {
311			l.data.Plans = original
312			return nil, err
313		}
314		return clonePlanPtr(l.findPlan(number)), nil
315	}
316	
317	// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
318	// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
319	// 完成时间和证书编号；超差证书同样表示校准工作已完成。
320	//
321	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
322	// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
323	// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
324	// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
325	// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
326	// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
327	// 完成时间取本次成功操作而非失败时刻。
328	//
329	// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
330	// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
331	// 计划均拒绝。
332	//
333	// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
334	// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
335	// 因此拿去完成另一项计划，完成时间也不会被刷新。
336	func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
337		number, err := cleanText(number)
338		if err != nil {
339			return nil, false, fmt.Errorf("计划编号无效：%w", err)
340		}
341		certificateNumber, err = cleanText(certificateNumber)
342		if err != nil {
343			return nil, false, fmt.Errorf("证书编号无效：%w", err)
344		}
345		p := l.findPlan(number)
346		if p == nil {
347			return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
348		}
349		// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
350		// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
351		// 仍保持完成、原证书仍算已用于该计划。
352		if p.Status == PlanStatusDone {
353			if p.CertificateNumber == certificateNumber {
354				return clonePlanPtr(p), true, nil
355			}
356			return nil, false, validationError(
357				"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
358				number, p.CertificateNumber)
359		}
360		if p.Status == PlanStatusCanceled {
361			return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
362		}
363	
364		cert := l.findCertificate(certificateNumber)
365		if cert == nil {
366			return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
367		}
368		if cert.InstrumentID != p.InstrumentID {
369			return nil, false, validationError(
370				"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
371				certificateNumber, cert.InstrumentID, p.InstrumentID, number)
372		}
373		// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
374		// 按日历日期比较，校准日期不得早于该日期（等于可以）。
375		created, perr := time.Parse(time.RFC3339, p.CreatedAt)
376		if perr != nil {
377			return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
378		}
379		createdDay := created.Format(DateLayout)
380		if cert.CalDate < createdDay {
381			return nil, false, validationError(
382				"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
383				certificateNumber, cert.CalDate, number, createdDay)
384		}
385		// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
386		for i := range l.data.Plans {
387			other := &l.data.Plans[i]
388			if other.Number != number && other.Status == PlanStatusDone &&
389				other.CertificateNumber == certificateNumber {
390				return nil, false, validationError(
391					"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
392					certificateNumber, other.Number)
393			}
394		}
395	
396		completedAt := l.now().Format(time.RFC3339)
397		// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
398		// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
399		// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
400		// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
401		original := l.data.Plans
402		staged := make([]Plan, len(original))
403		copy(staged, original)
404		for i := range staged {
405			if staged[i].Number != number {
406				continue
407			}
408			staged[i].Status = PlanStatusDone
409			staged[i].CompletedAt = completedAt
410			staged[i].CertificateNumber = certificateNumber
411		}
412		l.data.Plans = staged
413		if err := l.save(); err != nil {
414			l.data.Plans = original
415			return nil, false, err
416		}
417		return clonePlanPtr(l.findPlan(number)), false, nil
418	}
419	
420	// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
421	type TodoItem struct {
422		PlanNumber     string `json:"plan_number"`
423		InstrumentID   string `json:"instrument_id"`
424		InstrumentName string `json:"instrument_name"`
425		Status         Status `json:"status"`
426		PlannedDate    string `json:"planned_date"`
427		Note           string `json:"note"`
428		Marker         string `json:"marker"`
429	}
430	
431	// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
432	// 未来“未到计划日”。
433	func planMarker(plannedDate, todayText string) string {
434		switch {
435		case plannedDate < todayText:
436			return TodoOverdue
437		case plannedDate == todayText:
438			return TodoToday
439		default:
440			return TodoFuture
441		}
442	}
443	
444	// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
445	// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
446	// 同日按器具编号排列。查询不产生任何使用记录或写盘。
447	func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
448		id := strings.TrimSpace(instrumentID)
449		if id != "" && l.findInstrument(id) == nil {
450			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
451		}
452		todayText := l.now().Format(DateLayout)
453		items := []TodoItem{}
454		for _, p := range l.data.Plans {
455			if !p.Open() {
456				continue
457			}
458			if id != "" && p.InstrumentID != id {
459				continue
460			}
461			inst := l.findInstrument(p.InstrumentID)
462			if inst == nil {
463				continue
464			}
465			items = append(items, TodoItem{
466				PlanNumber:     p.Number,
467				InstrumentID:   inst.ID,
468				InstrumentName: inst.Name,
469				Status:         inst.Status,
470				PlannedDate:    p.PlannedDate,
471				Note:           p.Note,
472				Marker:         planMarker(p.PlannedDate, todayText),
473			})
474		}
475		sort.Slice(items, func(i, j int) bool {
476			if items[i].PlannedDate != items[j].PlannedDate {
477				return items[i].PlannedDate < items[j].PlannedDate
478			}
479			return items[i].InstrumentID < items[j].InstrumentID
480		})
481		return items, nil
482	}
483	
484	// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
485	// 改期记录和关联证书编号。
486	type PlanView struct {
487		Plan
488		Marker string `json:"marker"`
489	}
490	
491	// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
492	// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
493	// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
494	func (l *Ledger) plansOf(id string) []Plan {
495		var out []Plan
496		for _, p := range l.data.Plans {
497			if p.InstrumentID == id {
498				out = append(out, clonePlan(p))
499			}
500		}
501		sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
502		return out
503	}
504	
505	// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
506	func (l *Ledger) planViews(id string, today time.Time) []PlanView {
507		todayText := today.Format(DateLayout)
508		plans := l.plansOf(id)
509		out := make([]PlanView, 0, len(plans))
510		for _, p := range plans {
511			v := PlanView{Plan: p}
512			if p.Open() {
513				v.Marker = planMarker(p.PlannedDate, todayText)
514			}
515			out = append(out, v)
516		}
517		return out
518	}
519	
520	// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
521	// 器具不存在时报 ErrNotFound。返回的计划（含改期历史）都是独立展示副本：
522	// 调用方调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，
523	// 不回写台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
524	func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
525		id := strings.TrimSpace(instrumentID)
526		inst := l.findInstrument(id)
527		if inst == nil {
528			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
529		}
530		return l.planViews(id, l.now()), nil
531	}
532

file.content:
package calibrate

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
// 不能再改期、取消或重新开启。
const (
	PlanStatusOpen     = "未完成"
	PlanStatusDone     = "已完成"
	PlanStatusCanceled = "已取消"
)

// 待办相对本机今天的标记。
const (
	TodoToday   = "今天需校准"
	TodoOverdue = "逾期"
	TodoFuture  = "未到计划日"
)

// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
type PlanChange struct {
	From      string `json:"from"`
	To        string `json:"to"`
	ChangedAt string `json:"changed_at"`
	Reason    string `json:"reason"`
}

// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
type Plan struct {
	Number       string `json:"number"`
	InstrumentID string `json:"instrument_id"`
	// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
	PlannedDate  string       `json:"planned_date"`
	OriginalDate string       `json:"original_date"`
	Note         string       `json:"note"`
	CreatedAt    string       `json:"created_at"`
	Changes      []PlanChange `json:"changes,omitempty"`
	Status       string       `json:"status"`
	// 取消时保留原计划日期、取消时间和原因。
	CanceledAt   string `json:"canceled_at,omitempty"`
	CancelReason string `json:"cancel_reason,omitempty"`
	// 完成时保存完成时间和所用证书编号。
	CompletedAt       string `json:"completed_at,omitempty"`
	CertificateNumber string `json:"certificate_number,omitempty"`
}

// Open 报告计划是否尚未结束（未完成、未取消）。
func (p Plan) Open() bool { return p.Status == PlanStatusOpen }

// PlanInput 是建立校准计划的输入。
type PlanInput struct {
	Number       string
	InstrumentID string
	Date         string
	Note         string
}

func (l *Ledger) findPlan(number string) *Plan {
	for i := range l.data.Plans {
		if l.data.Plans[i].Number == number {
			return &l.data.Plans[i]
		}
	}
	return nil
}

// cloneChanges 返回改期历史切片的独立副本，使对外返回的计划与台账内部
// 存储不共享底层数组：调用方调换顺序、删改或追加展示用记录，不会改写
// 正式的改期历史。nil 保持 nil，以维持“没有改期历史”的既有表现。
func cloneChanges(in []PlanChange) []PlanChange {
	if in == nil {
		return nil
	}
	return append([]PlanChange(nil), in...)
}

// clonePlan 返回计划的独立深拷贝，连同改期历史一起复制。
func clonePlan(p Plan) Plan {
	p.Changes = cloneChanges(p.Changes)
	return p
}

// clonePlanPtr 返回台账内计划的独立深拷贝；找不到时返回 nil。
// 各计划操作返回的计划只是已保存内容的展示副本：调用方为了显示而改动
// 编号、日期、状态、关联证书或改期记录，都不能成为绕过计划操作直接改写
// 台账的途径，也不会在此后正常写盘时被带入台账文件。
func clonePlanPtr(p *Plan) *Plan {
	if p == nil {
		return nil
	}
	cp := clonePlan(*p)
	return &cp
}

// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于 now 所在的本机
// 日历日期。调用方传入本次操作开始时所取的本机时间，使日期合法性与操作
// 记录的时间对应同一时刻。
func (l *Ledger) validatePlanDate(raw, field string, now time.Time) (string, error) {
	_, text, err := parseFiniteDate(raw, field)
	if err != nil {
		return "", err
	}
	todayText := now.Format(DateLayout)
	if text < todayText {
		return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
	}
	return text, nil
}

// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
// 不新增或改动任何记录。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与建立前完全一致——
// 失败的计划既不占用编号，也不占用该器具唯一的未结束计划名额，更不会在此后
// 其他成功操作写盘时被顺带写入；文件仍不可写时再次提交相同编号仍报保存错误
// （不会被当成编号重复或器具已有未结束计划而拒绝），恢复可写后无需重新打开
// 台账，重新提交才真正建立，建立时间取本次成功申请的时间。
//
// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
// 重新查询同一台账得到的仍是最后成功保存的计划。
// 每次建立申请只在开始处理时取一次本机时间：计划日期是否不早于“今天”
// 按该时刻的日历日期判断，正式保存的建立时间也取该时刻——即使校验与写盘
// 之间跨过午夜，建立时间仍属于申请开始的日历日期，当天计划不会被记成
// 次日建立，也不会在随后用申请当天的证书完成时被误判为证书早于建立。
// 该时刻不延续到下一次申请：下次建立重新取当时的本机时间判断。
func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
	now := l.now()
	number, err := cleanText(in.Number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	instID, err := cleanText(in.InstrumentID)
	if err != nil {
		return nil, fmt.Errorf("器具编号无效：%w", err)
	}
	note, err := cleanText(in.Note)
	if err != nil {
		return nil, fmt.Errorf("计划说明无效：%w", err)
	}
	if l.findInstrument(instID) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
	}
	dateText, err := l.validatePlanDate(in.Date, "计划日期", now)
	if err != nil {
		return nil, err
	}
	if l.findPlan(number) != nil {
		return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
	}
	for i := range l.data.Plans {
		p := &l.data.Plans[i]
		if p.InstrumentID == instID && p.Open() {
			return nil, validationError(
				"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
				instID, p.Number, p.PlannedDate)
		}
	}
	p := Plan{
		Number:       number,
		InstrumentID: instID,
		PlannedDate:  dateText,
		OriginalDate: dateText,
		Note:         note,
		CreatedAt:    now.Format(time.RFC3339),
		Status:       PlanStatusOpen,
	}
	// 在独立的新切片上暂存新计划：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片，保证同一台账对象随后看到的计划查询、待办与
	// 按器具核对都与建立前一致——失败计划不占用编号或该器具唯一的未结束
	// 计划名额，再次提交仍会走到保存而不会被当成重复计划拒绝，失败计划也
	// 不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, 0, len(original)+1)
	staged = append(staged, original...)
	staged = append(staged, p)
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
	p := l.findPlan(number)
	if p == nil {
		return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	if !p.Open() {
		return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
			number, p.Status)
	}
	return p, nil
}

// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
// 找不到计划或计划已结束时拒绝且不改动记录。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
// 且只新增一条从最后成功保存的日期到新日期的记录。
//
// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
// 此前分别取得的操作结果、计划查询结果和核对结果。
func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
	// 本次改期只取一次本机时间：新日期的合法性判断与留痕的操作时间对应
	// 同一时刻，跨午夜不会分裂到两天。
	now := l.now()
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("改期原因无效：%w", err)
	}
	dateText, err := l.validatePlanDate(newDate, "新计划日期", now)
	if err != nil {
		return nil, err
	}
	p, err := l.requireOpenPlan(number)
	if err != nil {
		return nil, err
	}
	// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
	change := PlanChange{
		From:      p.PlannedDate,
		To:        dateText,
		ChangedAt: now.Format(time.RFC3339),
		Reason:    reason,
	}
	// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
	// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
		staged[i].PlannedDate = dateText
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
// 取消，取消时间和原因取本次成功提交而非失败那次。
//
// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("取消原因无效：%w", err)
	}
	if _, err := l.requireOpenPlan(number); err != nil {
		return nil, err
	}
	canceledAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
	// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
	// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusCanceled
		staged[i].CanceledAt = canceledAt
		staged[i].CancelReason = reason
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
// 完成时间和证书编号；超差证书同样表示校准工作已完成。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
// 完成时间取本次成功操作而非失败时刻。
//
// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
// 计划均拒绝。
//
// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
// 因此拿去完成另一项计划，完成时间也不会被刷新。
func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, false, fmt.Errorf("计划编号无效：%w", err)
	}
	certificateNumber, err = cleanText(certificateNumber)
	if err != nil {
		return nil, false, fmt.Errorf("证书编号无效：%w", err)
	}
	p := l.findPlan(number)
	if p == nil {
		return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
	// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
	// 仍保持完成、原证书仍算已用于该计划。
	if p.Status == PlanStatusDone {
		if p.CertificateNumber == certificateNumber {
			return clonePlanPtr(p), true, nil
		}
		return nil, false, validationError(
			"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
			number, p.CertificateNumber)
	}
	if p.Status == PlanStatusCanceled {
		return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
	}

	cert := l.findCertificate(certificateNumber)
	if cert == nil {
		return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
	}
	if cert.InstrumentID != p.InstrumentID {
		return nil, false, validationError(
			"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
			certificateNumber, cert.InstrumentID, p.InstrumentID, number)
	}
	// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
	// 按日历日期比较，校准日期不得早于该日期（等于可以）。
	created, perr := time.Parse(time.RFC3339, p.CreatedAt)
	if perr != nil {
		return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
	}
	createdDay := created.Format(DateLayout)
	if cert.CalDate < createdDay {
		return nil, false, validationError(
			"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
			certificateNumber, cert.CalDate, number, createdDay)
	}
	// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
	for i := range l.data.Plans {
		other := &l.data.Plans[i]
		if other.Number != number && other.Status == PlanStatusDone &&
			other.CertificateNumber == certificateNumber {
			return nil, false, validationError(
				"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
				certificateNumber, other.Number)
		}
	}

	completedAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
	// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
	// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusDone
		staged[i].CompletedAt = completedAt
		staged[i].CertificateNumber = certificateNumber
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, false, err
	}
	return clonePlanPtr(l.findPlan(number)), false, nil
}

// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
type TodoItem struct {
	PlanNumber     string `json:"plan_number"`
	InstrumentID   string `json:"instrument_id"`
	InstrumentName string `json:"instrument_name"`
	Status         Status `json:"status"`
	PlannedDate    string `json:"planned_date"`
	Note           string `json:"note"`
	Marker         string `json:"marker"`
}

// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
// 未来“未到计划日”。
func planMarker(plannedDate, todayText string) string {
	switch {
	case plannedDate < todayText:
		return TodoOverdue
	case plannedDate == todayText:
		return TodoToday
	default:
		return TodoFuture
	}
}

// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
// 同日按器具编号排列。查询不产生任何使用记录或写盘。
func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
	id := strings.TrimSpace(instrumentID)
	if id != "" && l.findInstrument(id) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	todayText := l.now().Format(DateLayout)
	items := []TodoItem{}
	for _, p := range l.data.Plans {
		if !p.Open() {
			continue
		}
		if id != "" && p.InstrumentID != id {
			continue
		}
		inst := l.findInstrument(p.InstrumentID)
		if inst == nil {
			continue
		}
		items = append(items, TodoItem{
			PlanNumber:     p.Number,
			InstrumentID:   inst.ID,
			InstrumentName: inst.Name,
			Status:         inst.Status,
			PlannedDate:    p.PlannedDate,
			Note:           p.Note,
			Marker:         planMarker(p.PlannedDate, todayText),
		})
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].PlannedDate != items[j].PlannedDate {
			return items[i].PlannedDate < items[j].PlannedDate
		}
		return items[i].InstrumentID < items[j].InstrumentID
	})
	return items, nil
}

// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
// 改期记录和关联证书编号。
type PlanView struct {
	Plan
	Marker string `json:"marker"`
}

// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
func (l *Ledger) plansOf(id string) []Plan {
	var out []Plan
	for _, p := range l.data.Plans {
		if p.InstrumentID == id {
			out = append(out, clonePlan(p))
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
	return out
}

// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
func (l *Ledger) planViews(id string, today time.Time) []PlanView {
	todayText := today.Format(DateLayout)
	plans := l.plansOf(id)
	out := make([]PlanView, 0, len(plans))
	for _, p := range plans {
		v := PlanView{Plan: p}
		if p.Open() {
			v.Marker = planMarker(p.PlannedDate, todayText)
		}
		out = append(out, v)
	}
	return out
}

// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
// 器具不存在时报 ErrNotFound。返回的计划（含改期历史）都是独立展示副本：
// 调用方调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，
// 不回写台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
	id := strings.TrimSpace(instrumentID)
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	return l.planViews(id, l.now()), nil
}

